using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;
public static class BuildComboPreparationSteps
{
 class Pose {public Vector3[] p,s;public Quaternion[] q;}
 static Pose Read(Transform[] t)=>new Pose{p=t.Select(x=>x.localPosition).ToArray(),q=t.Select(x=>x.localRotation).ToArray(),s=t.Select(x=>x.localScale).ToArray()};
 static void Apply(Transform[] t,Pose p){for(int i=0;i<t.Length;i++){t[i].localPosition=p.p[i];t[i].localRotation=p.q[i];t[i].localScale=p.s[i];}}
 static void Blend(Transform[] t,Pose a,Pose b,float u){for(int i=0;i<t.Length;i++){t[i].localPosition=Vector3.Lerp(a.p[i],b.p[i],u);t[i].localRotation=Quaternion.Slerp(a.q[i],b.q[i],u);t[i].localScale=Vector3.Lerp(a.s[i],b.s[i],u);}}
 static void IK(Transform upper,Transform lower,Transform foot,Vector3 target){Vector3 origin=upper.position;float l1=Vector3.Distance(origin,lower.position),l2=Vector3.Distance(lower.position,foot.position);var dir=(target-origin).normalized;float d=Mathf.Clamp(Vector3.Distance(origin,target),Mathf.Abs(l1-l2)+.00001f,l1+l2-.00001f);var pole=Vector3.ProjectOnPlane(lower.position-origin,dir).normalized;if(pole.sqrMagnitude<.01f)pole=Vector3.ProjectOnPlane(Vector3.forward,dir).normalized;float x=(l1*l1-l2*l2+d*d)/(2*d);var knee=origin+dir*x+pole*Mathf.Sqrt(Mathf.Max(0,l1*l1-x*x));upper.rotation=Quaternion.FromToRotation(lower.position-origin,knee-origin)*upper.rotation;lower.rotation=Quaternion.FromToRotation(foot.position-lower.position,origin+dir*d-lower.position)*lower.rotation;}
 public static object Run()
 {
  if(Application.isPlaying)throw new Exception("Stop play mode first");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.name!="3DBattleDebugScene")throw new Exception("Wrong scene");var live=GameObject.Find("New Knight Combo Sequence Preview");if(live==null)throw new Exception("Missing combo");foreach(var w in Resources.FindObjectsOfTypeAll<AnimationWindow>()){w.recording=false;w.previewing=false;}if(AnimationMode.InAnimationMode())AnimationMode.StopAnimationMode();
  string[] names={"Attack 05 - Skill_03","Attack 02 - Charged_Upward_Slash","Attack 03 - Double_Combo_Attack","Attack 06 - Weapon_Combo_1","Attack 05 - Skill_03","Attack 04 - Right_Hand_Sword_Slash","Attack 01 - Attack"};int[] starts={0,21,0,4,0,8,15},ends={16,42,41,39,16,22,33};var sources=names.Select(GameObject.Find).ToArray();var clips=sources.Select(s=>s.GetComponentInChildren<Animator>().runtimeAnimatorController.animationClips[0]).ToArray();var paths=clips.SelectMany(c=>AnimationUtility.GetCurveBindings(c)).Select(b=>b.path).Distinct().OrderBy(p=>p.Count(ch=>ch=='/')).ToArray();
  var root=UnityEngine.Object.Instantiate(live);root.name="Temporary preparation builder";root.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var animator=root.GetComponentInChildren<Animator>();animator.enabled=false;var nodes=paths.Select(p=>animator.transform.Find(p)).ToArray();if(nodes.Any(t=>t==null))throw new Exception("Missing node");var all=root.GetComponentsInChildren<Transform>();Func<string,Transform> bone=n=>all.First(t=>t.name==n);var hip=bone("Hips");var feet=new[]{bone("LeftFoot"),bone("RightFoot")};var uppers=new[]{bone("LeftUpperLeg"),bone("RightUpperLeg")};var lowers=new[]{bone("LeftLowerLeg"),bone("RightLowerLeg")};
  var errors=new List<string>();Application.LogCallback log=(m,s,t)=>{if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m);};Application.logMessageReceived+=log;var records=paths.ToDictionary(p=>p,p=>Enumerable.Range(0,10).Select(_=>new List<Keyframe>()).ToArray());var expected=new List<Pose>();var sampleTimes=new List<float>();var ranges=new List<object>();var transitions=new List<object>();var attackStarts=new List<int>();var shifts=new List<Vector3>();int offset=0;Pose previous=null;float maxFootError=0,maxSupportDrift=0;int steps=0;
  Action<float> capture=frame=>{var pose=Read(nodes);expected.Add(pose);sampleTimes.Add(frame/30f);for(int n=0;n<paths.Length;n++)for(int c=0;c<10;c++)records[paths[n]][c].Add(new Keyframe(frame/30f,c<3?pose.p[n][c]:c<7?pose.q[n][c-3]:pose.s[n][c-7]));};
  try{
   for(int seg=0;seg<7;seg++){
    var temp=UnityEngine.Object.Instantiate(sources[seg]);try{temp.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var sa=temp.GetComponentInChildren<Animator>();sa.enabled=false;var sn=paths.Select(p=>sa.transform.Find(p)).ToArray();var sh=temp.GetComponentsInChildren<Transform>().First(t=>t.name=="Hips");clips[seg].SampleAnimation(sa.gameObject,starts[seg]/30f);var start=Read(sn);Vector3 shift=Vector3.zero;
     if(seg>0){Apply(nodes,previous);var oldFeet=feet.Select(f=>f.position).ToArray();var oldRot=feet.Select(f=>f.rotation).ToArray();var oldHip=hip.position;int oldLead=oldFeet[0].z>oldFeet[1].z?0:1;Apply(nodes,start);var newFeet=feet.Select(f=>f.position).ToArray();int newLead=newFeet[0].z>newFeet[1].z?0:1;bool swap=oldLead!=newLead;shift=swap?oldFeet[oldLead]-newFeet[oldLead]:oldHip-hip.position;shift.y=0;sh.position+=shift;start=Read(sn);Apply(nodes,start);var targetFeet=feet.Select(f=>f.position).ToArray();var targetRot=feet.Select(f=>f.rotation).ToArray();int first=offset;float stepTravel=targetFeet[newLead].z-oldFeet[newLead].z;
      for(int half=1;half<12;half++){float alpha=half/12f;float u=alpha*alpha*alpha*(alpha*(alpha*6-15)+10);Blend(nodes,previous,start,u);if(swap){var targets=new[]{Vector3.Lerp(oldFeet[0],targetFeet[0],u),Vector3.Lerp(oldFeet[1],targetFeet[1],u)};targets[newLead]+=Vector3.up*(.14f*16*alpha*alpha*(1-alpha)*(1-alpha));
       // Keep both foot targets reachable without stretching the legs.
       var lengths=Enumerable.Range(0,2).Select(j=>Vector3.Distance(uppers[j].position,lowers[j].position)+Vector3.Distance(lowers[j].position,feet[j].position)-.0002f).ToArray();var hipOffsets=uppers.Select(t=>t.position-hip.position).ToArray();for(int it=0;it<12;it++)for(int j=0;j<2;j++){var center=targets[j]-hipOffsets[j];hip.position=center+Vector3.ClampMagnitude(hip.position-center,lengths[j]);}
       for(int j=0;j<2;j++){IK(uppers[j],lowers[j],feet[j],targets[j]);feet[j].rotation=Quaternion.Slerp(oldRot[j],targetRot[j],u);maxFootError=Mathf.Max(maxFootError,Vector3.Distance(feet[j].position,targets[j]));}maxSupportDrift=Mathf.Max(maxSupportDrift,Vector3.ProjectOnPlane(feet[oldLead].position-oldFeet[oldLead],Vector3.up).magnitude);
      }capture(offset-1+half*.5f);}
      if(swap)steps++;transitions.Add(new{from=names[seg-1],to=names[seg],firstFrame=first,lastFrame=first+4,previousFrontFoot=oldLead==0?"Left":"Right",nextFrontFoot=newLead==0?"Left":"Right",step=swap,stepForwardDistance=stepTravel});offset+=5;
     }
     shifts.Add(shift);attackStarts.Add(offset);ranges.Add(new{order=seg+1,motion=names[seg],sourceFirst=starts[seg],sourceLast=ends[seg],comboFirst=offset,comboLast=offset+ends[seg]-starts[seg]});for(int half=0;half<=(ends[seg]-starts[seg])*2;half++){clips[seg].SampleAnimation(sa.gameObject,starts[seg]/30f+half/60f);sh.position+=shift;Apply(nodes,Read(sn));capture(offset+half*.5f);}previous=Read(nodes);offset+=ends[seg]-starts[seg]+1;
    }finally{UnityEngine.Object.DestroyImmediate(temp);}
   }
   var result=new AnimationClip{name="NewKnight_ComboSequence_Preparation5",frameRate=30};var bindings=new List<EditorCurveBinding>();var curves=new List<AnimationCurve>();foreach(var pair in records){var r=pair.Value;for(int i=1;i<r[0].Count;i++){float dot=0;for(int c=3;c<7;c++)dot+=r[c][i-1].value*r[c][i].value;if(dot<0)for(int c=3;c<7;c++){var key=r[c][i];key.value=-key.value;r[c][i]=key;}}
    for(int c=0;c<10;c++){var curve=new AnimationCurve(r[c].ToArray());for(int k=0;k<curve.length;k++){AnimationUtility.SetKeyLeftTangentMode(curve,k,AnimationUtility.TangentMode.Linear);AnimationUtility.SetKeyRightTangentMode(curve,k,AnimationUtility.TangentMode.Linear);}bindings.Add(EditorCurveBinding.FloatCurve(pair.Key,typeof(Transform),c<3?"m_LocalPosition."+"xyz"[c]:c<7?"m_LocalRotation."+"xyzw"[c-3]:"m_LocalScale."+"xyz"[c-7]));curves.Add(curve);}}
   AnimationUtility.SetEditorCurves(result,bindings.ToArray(),curves.ToArray());var settings=AnimationUtility.GetAnimationClipSettings(result);settings.loopTime=true;settings.loopBlend=false;AnimationUtility.SetAnimationClipSettings(result,settings);
   float positionError=0,rotationError=0;for(int i=0;i<sampleTimes.Count;i++){result.SampleAnimation(animator.gameObject,sampleTimes[i]);for(int j=0;j<nodes.Length;j++){positionError=Mathf.Max(positionError,Vector3.Distance(nodes[j].localPosition,expected[i].p[j]));rotationError=Mathf.Max(rotationError,Quaternion.Angle(nodes[j].localRotation,expected[i].q[j]));}}
   if(positionError>.001f||rotationError>.1f||maxFootError>.015f||errors.Count>0)throw new Exception("Validation: "+positionError+" / "+rotationError+" / feet "+maxFootError+" / "+string.Join(" | ",errors));
   const string folder="Assets/3DBattle/NewPlayer/Attack/ComboPreview";string asset=AssetDatabase.GenerateUniqueAssetPath(folder+"/"+result.name+".anim");AssetDatabase.CreateAsset(result,asset);var controller=AnimatorController.CreateAnimatorControllerAtPath(AssetDatabase.GenerateUniqueAssetPath(folder+"/"+result.name+".controller"));var state=controller.layers[0].stateMachine.AddState("Combo with preparation steps");state.motion=result;controller.layers[0].stateMachine.defaultState=state;
   var report=new{objectName=live.name,attackRanges=ranges,transitions,totalFrames=offset,lastFrame=offset-1,duration=result.length,stepTransitions=steps,maxFootTargetError=maxFootError,maxSupportHorizontalDrift=maxSupportDrift,positionError,rotationError,clip=asset};AssetDatabase.CreateAsset(new TextAsset(Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented)){name="Combo_Preparation5_Ranges"},AssetDatabase.GenerateUniqueAssetPath(folder+"/Combo_Preparation5_Ranges.asset"));AssetDatabase.SaveAssets();var liveA=live.GetComponentInChildren<Animator>();Undo.RecordObject(liveA,"Add combo preparation steps");liveA.runtimeAnimatorController=controller;result.SampleAnimation(liveA.gameObject,0);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Selection.activeGameObject=live;return report;
  }finally{Application.logMessageReceived-=log;UnityEngine.Object.DestroyImmediate(root);}
 }
}
